#!/bin/sh
# vibTTY / Ghostty  kitty 图形协议对齐诊断
#
#   A  原样      ratatui-image 现在发的：虚拟放置不带 c/r，每行 CSI s 开头、
#                CSI u + 相对移动收尾
#   B  补 c/r    传输里显式给出 c=4,r=2
#   C  去收尾    不用 CSI s / CSI u，改绝对列定位
#   D  最小例    一行高的图 + 同一行的标签，只考验占位符落在哪一行
#
# 读法：
#   A 拆成两块、C 是整块  → CSI s / CSI u（SCOSC/SCORC）没实现
#   D 的方块和标签不同行  → 占位符的行定位差一行，与 c/r 和光标都无关
#
# 在真 Ghostty 上跑同一个脚本做对照。

printf "终端: ${TERM_PROGRAM:-?} ${TERM_PROGRAM_VERSION:-?}  TERM=${TERM:-?}\n\n"

printf "A  原样（ratatui-image 现在发的）\n"
printf '\033_Gq=2,i=11189196,a=T,U=1,f=32,t=d,s=64,v=70,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\033[s\033[38;2;170;187;204m􎻮̅̅̅􎻮􎻮􎻮\033[u\033[3C\033[1B'
printf '  ← 上边应与本行齐平\n'
printf '\033[s\033[38;2;170;187;204m􎻮̍̅̅􎻮􎻮􎻮\033[u\033[3C\033[1B'
printf '  ← 下边应与本行齐平\n'
printf "\n"
printf "B  传输里补上 c=4,r=2\n"
printf '\033_Gq=2,i=11189197,a=T,U=1,f=32,t=d,s=64,v=70,c=4,r=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\033[s\033[38;2;170;187;204m􎻮̅̅̅􎻮􎻮􎻮\033[u\033[3C\033[1B'
printf '  ← 上边应与本行齐平\n'
printf '\033[s\033[38;2;170;187;204m􎻮̍̅̅􎻮􎻮􎻮\033[u\033[3C\033[1B'
printf '  ← 下边应与本行齐平\n'
printf "\n"
printf "C  收尾改绝对列定位，不用 CSI s/u\n"
printf '\033_Gq=2,i=11189198,a=T,U=1,f=32,t=d,s=64,v=70,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\r\033[38;2;170;187;204m􎻮̅̅̅􎻮􎻮􎻮\033[0m\033[7G← 上边应与本行齐平\n'
printf '\r\033[38;2;170;187;204m􎻮̍̅̅􎻮􎻮􎻮\033[0m\033[7G← 下边应与本行齐平\n'
printf "\n"
printf "D  最小例：一行高的图，标签在同一行\n"
printf '\033_Gq=2,i=11189199,a=T,U=1,f=32,t=d,s=64,v=35,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\r\033[38;2;170;187;204m􎻮̅̅̅􎻮􎻮􎻮\033[0m\033[7G← 方块应当整个落在本行\n'
printf "\n"
printf "D 里方块和标签不在同一行，就是占位符的行定位差了一行。\n"
